#include <stdlib.h>

int main(int argc, char *argv[]) {
    // open the file
    FILE* f = fopen("file.txt", "r");
    if(f == NULL) {
        printf("Error opening file\n");
        return 1;
    }

    // read the file
    char buf[1024];
    int i = 0;
    while(i < 1024) {
        buf[i] = fgetc(f);
        if(buf[i] == EOF) {
            break;
        }
        i++;
    }
    buf[i] = '\0';

    // print the buffer
    printf("Buffer: %s\n", buf);

