### 3. Calculate mean, median, mode, and standard deviation

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define FILENAME "data.csv"

int main(int argc, char *argv[]) {
    // read data from file
	FILE *fp = fopen(FILENAME, "r");
	char line[100];
	int count = 0;
	float sum = 0;
	float mean = 0;
	float median = 0;
	float mode = 0;
	float stddev = 0;
	while (fgets(line, sizeof(line), fp)) {
		count++;
		float value = atof(line);
		sum += value;
		if (count == 1) {
			mode = value;
		}
		if (count == 2) {
			median = value;
		}
	}
	mean = sum / count;
	stddev = sqrt(sum / count - mean * mean);
	fclose(fp);

	// print results
	printf("Count: %d\n", count);
	printf("Sum: %f\n", sum);
	printf("Mean: %f\n", mean);
	printf("Median: %f\n", median);
	printf("Mode: %f\n", mode);
	printf("Standard Deviation: %f\n", stddev);

	return 0;
}
```

