内存分配的函数是`malloc()`，它接受一个参数，即要分配的内存大小，单位是字节。

```c
#include <stdio.h>
#include <stdlib.h>

int* allocateMemory(int size) {
    /* allocate memory for an array of integers */
    int *array = malloc(sizeof(int)*size);
    if(array == NULL) {
        printf("Error allocating memory\n");
        return NULL;
    }
    return array;
}

int main(int argc, char *argv[]) {
    int *array = NULL;
    int size = 10;

    /* allocate memory */
    array = allocateMemory(size);
    if(array == NULL) {
        return 1;
    }

    /* fill the array with values */
    for(int i = 0; i < size; i++) {
        array[i] = i;
    }

    /* print the array */
    for(int i = 0; i < size; i++) {
        printf("%d ", array[i]);
    }
    printf("\n");

    /* free the memory */
    free(array);

    return 0;
}
```

