### 2.2.2. 内存映射文件

内存映射文件是一种特殊的文件，它将文件内容映射到内存中，从而可以直接访问文件内容而不必再次读取。

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>

int main(int argc, char *argv[]) { 
    char* important_config = "important_config";

    // save the important config to a file
	int fd = open(important_config, O_CREAT | O_WRONLY, 0644);
	if (fd == -1) {
		perror("open");
		exit(1);
	}
	write(fd, "important_config_value", 22);
	close(fd);

    // map the important config to memory
	void* map = mmap(NULL, 22, PROT_READ, MAP_PRIVATE, fd, 0);
	if (map == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

    // read the important config from memory
	printf("Important config: %s\n", map);

	return 0;
}
