### 2.2.2.2. 遍历目录树

```c
#include <sys/types.h>
#include <sys/stat.h>
#include <dirent.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // get a directory name from the command line
    char *dirname = argv[1];

    // open the directory for reading
    int dirfd = open(dirname, O_RDONLY);
    if (dirfd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // read the directory entries
    struct dirent *entry;
    while ((entry = readdir(dirfd))!= NULL) {
        // skip "." and ".."
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // get the full path of the entry
        char path[256] = {0};
        sprintf(path, "%s/%s", dirname, entry->d_name);

        // get the entry's stat information
        struct stat statbuf = {0};
        if (stat(path, &statbuf) == -1) {
            perror("stat");
            exit(EXIT_FAILURE);
        }

        // print the entry's name and type
        printf("%s: ", entry->d_name);
        switch (statbuf.st_mode & S_IFMT) {
            case S_IFDIR:
                printf("directory\n");
                break;
            case S_IFREG:
                printf("regular file\n");
                break;
            case S_IFLNK:
                printf("symbolic link\n");
                break;
            default:
                printf("unknown\n");
                break;
        }

        // recursively list the entry if it is a directory
        if (statbuf.st_mode & S_IFDIR) {
            main(2, &path);
        }
    }

    // close the directory
    close(dirfd);

    return 0;
}
