```c
#include <dirent.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>

int main(int argc, char *argv[]) {
    // get a directory name from the command line
    char *dirname = argv[1];

    // open the directory for reading
    int dirfd = open(dirname, O_RDONLY);
    if (dirfd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // read the directory entries
    struct dirent *entry;
    while ((entry = readdir(dirfd))!= NULL) {
        // skip "." and ".." entries
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

