  if (argc!= 2) {
    fprintf(stderr, "Usage: %s port\n", argv[0]);
    exit(1);
  }

  int port = atoi(argv[1]);
  char* url = "http://localhost:" + argv[1];

  // open a socket to listen on
  int listenfd = socket(AF_INET, SOCK_STREAM, 0);
  if (listenfd < 0) {
    perror("socket");
    exit(1);
  }

  // bind the socket to the port
  struct sockaddr_in address;
  address.sin_family = AF_INET;
  address.sin_addr.s_addr = INADDR_ANY;
  address.sin_port = htons(port);
  if (bind(listenfd, (struct sockaddr*)&address, sizeof(address)) < 0) {
    perror("bind");
    exit(1);
  }

  // listen for connections
  if (listen(listenfd, 10) < 0) {
    perror("listen");
    exit(1);
  }

  // accept a connection
  struct sockaddr_in client;
  socklen_t clientlen = sizeof(client);
  int connfd = accept(listenfd, (struct sockaddr*)&client, &clientlen);
  if (connfd < 0) {
    perror("accept");
    exit(1);
  }

  // read the request
  char requestbuf[1024];
  int n = read(connfd, requestbuf, 1024);
  if (n < 0) {
    perror("read");
    exit(1);
  }

  // parse the request
  char method[1024];
  char url[1024];
  sscanf(requestbuf, "%s %s", method, url);

  // handle the request
  http_hello_page(url, method, connfd, connfd);

  // close the connection
  close(connfd);
  close(listenfd);
}

