int main(int argc, char *argv[]) {
    const char* message1 = "Hello";
    const char* message2 = "World";
    char buffer[256];

    // copy the message to the buffer
    memcpy(buffer, message1, strlen(message1));

    // append the second message to the buffer
    strcat(buffer, message2);

