```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    const char* message = "Hello World";
    char buffer[256];

    // copy the message to the buffer
    memcpy(buffer, message, strlen(message));

    // find the first occurrence of the character 'o'
    char* result = strchr(buffer, 'o');

    if (result!= NULL) {
        printf("The character 'o' is found at position %d.\n", result - buffer);
    } else {
        printf("The character 'o' is not found.\n");
    }

    // find the first occurrence of the string "World"
    result = strstr(buffer, "World");

    if (result!= NULL) {
        printf("The string 'World' is found at position %d.\n", result - buffer);
    } else {
        printf("The string 'World' is not found.\n");
    }

    return 0;
}
```

