#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    const char* message = "Hello World";
    char buffer[256];

    // copy the message to the buffer
    memcpy(buffer, message, strlen(message));

    // replace the character 'o' with 'a'
    char* result = strchr(buffer, 'o');

    if (result!= NULL) {
        *result = 'a';
    }

    // replace the string "World" with "Universe"
    result = strstr(buffer, "World");

    if (result!= NULL) {
